package sfz.shard.l04.demo

import java.nio.ByteBuffer
import java.security.MessageDigest

fun shardFor(key: String, shards: Int): Int =
    Math.floorMod(ByteBuffer.wrap(MessageDigest.getInstance("MD5").digest(key.toByteArray())).long, shards.toLong()).toInt()

/** 10,000 payments over 1,000 cards, sharded by payment id. The fraud check asks: what has card-242 done? */
fun main() {
    val payments = (0 until 10_000).map { "pay-$it" to "card-${it % 1_000}" }
    for (shards in listOf(8, 32)) {
        val rowShard = payments.associate { (id, _) -> id to shardFor(id, shards) }
        val card242 = payments.filter { it.second == "card-242" }.map { it.first }
        println("$shards shards; card-242 has ${card242.size} payments, on shards ${card242.map { rowShard.getValue(it) }.sorted()}")
        println("  find pay-1234 by id:            asks 1 shard")
        // local index: each shard indexes its own rows, so all of them must be asked
        println("  find by card, local index:      asks $shards shards; each payment writes 1 shard")
        // global index: all of card-242's entries sit on one index shard, then fetch the rows
        val rowShards = card242.map { rowShard.getValue(it) }.toSet().size
        println("  find by card, global index:     asks 1 index shard + $rowShards row shards; each payment writes 2 shards")
        println("  2,000 fraud checks a second cost ${"%,d".format(2_000 * shards)} shard requests with the local index, ${"%,d".format(2_000 * (1 + rowShards))} with the global one")
    }
}

package sfz.shard.l04.demo

import java.util.Random

/** Each shard answers in 2 to 3 ms, except 1 time in 100 it takes 50 ms. A scatter-gather waits for the slowest. */
fun main() {
    val rnd = Random(42)
    fun shardMillis() = if (rnd.nextInt(100) == 0) 50.0 else 2.0 + rnd.nextDouble()
    fun pct(sorted: List<Double>, p: Double) = sorted[maxOf(0, Math.ceil(p / 100 * sorted.size).toInt() - 1)]
    println("shards asked   p50 ms   p90 ms   p99 ms   queries over 10 ms   1 - 0.99^shards")
    for (shards in listOf(1, 2, 5, 10, 20, 50, 100)) {
        val q = List(20_000) { (1..shards).maxOf { shardMillis() } }.sorted()
        val slow = q.count { it > 10.0 } / 200.0
        println("%12d   %6.1f   %6.1f   %6.1f   %17.1f%%   %14.1f%%".format(
            shards, pct(q, 50.0), pct(q, 90.0), pct(q, 99.0), slow, (1 - Math.pow(0.99, shards.toDouble())) * 100))
    }
}

package sfz.shard.l04.demo

import java.util.Random

/**
 * A model of an asynchronous global index, on virtual time. Each index entry lands some time after its
 * row: here 30 to 120 ms, and 1 time in 50 it takes 600 ms (a busy index shard). These lags are made
 * up for the model; DynamoDB only promises "a fraction of a second, under normal conditions".
 * The fraud check reads the index some milliseconds after each payment. How often is it missing?
 */
fun main() {
    val rnd = Random(7)
    val lags = List(10_000) { if (rnd.nextInt(50) == 0) 600L else 30L + rnd.nextInt(91) }
    println("check runs after   index still missing the payment")
    for (after in listOf(10L, 50L, 100L, 250L, 1_000L)) {
        val missing = lags.count { it > after }
        println("%13d ms   %,6d of 10,000 (%.1f%%)".format(after, missing, missing / 100.0))
    }
    println("reading the row by its key: 0 of 10,000 missing, at any time")
}

