fun findLocal(localIndex: List<Map<String, Set<String>>>, card: String): Pair<Set<String>, Int> =
    // every shard may hold some of the card's rows: ask them all
    localIndex.flatMap { it[card].orEmpty() }.toSet() to localIndex.size

fun findGlobal(globalIndex: List<Map<String, Set<String>>>, card: String, rowShardOf: (String) -> Int): Pair<Set<String>, Int> {
    // one index shard holds every entry for this card
    val ids = globalIndex[shardFor(card, globalIndex.size)][card].orEmpty()
    return ids to 1 + ids.map(rowShardOf).toSet().size // plus the shards that hold the rows
}
// A global index needs a second write, to another machine, for every indexed column of every row:
// either in a distributed transaction or asynchronously, and then reads through it can be stale.
